<!doctype html>
<html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kundeportal · Nodexa</title><style>
:root{--bg:#07111c;--side:#091522;--card:#0e1d2c;--card2:#122538;--line:#1d3448;--text:#eef6ff;--muted:#7f96aa;--blue:#3988ff;--green:#35d58b;--orange:#ffb84a;--red:#ff6574}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.app{display:grid;grid-template-columns:245px 1fr;min-height:100vh}.sidebar{background:var(--side);border-right:1px solid var(--line);padding:22px 14px;position:sticky;top:0;height:100vh}.logo{font-weight:850;font-size:21px;padding:4px 12px 27px}.logo b{color:var(--blue)}.group{font-size:10px;letter-spacing:.12em;color:#52708a;font-weight:800;padding:18px 12px 7px}.nav a{display:flex;gap:11px;align-items:center;color:#91a6b8;text-decoration:none;padding:11px 12px;border-radius:7px;margin:2px 0;font-size:13px}.nav a:hover,.nav a.active{background:#102b43;color:#fff}.nav i{width:18px;text-align:center;font-style:normal}.content{padding:28px;max-width:1500px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.top h1{font-size:24px;margin:0 0 5px}.muted{color:var(--muted)}.profile{background:var(--card);border:1px solid var(--line);padding:9px 13px;border-radius:8px;font-size:13px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat,.panel{background:var(--card);border:1px solid var(--line);border-radius:8px}.stat{padding:17px}.stat .num{font-size:25px;font-weight:800;margin-top:7px}.stat .label{font-size:12px;color:var(--muted)}.main-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(270px,.8fr);gap:16px;margin-top:16px}.panel{overflow:hidden;margin-bottom:16px}.head{padding:14px 16px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.head h2{font-size:14px;margin:0}.body{padding:16px}.btn{display:inline-block;border:0;background:var(--blue);color:white;text-decoration:none;padding:8px 11px;border-radius:6px;font-weight:700;font-size:12px}.btn.secondary{background:#19344d}.service{display:grid;grid-template-columns:minmax(0,1.6fr) 1fr 1fr auto;gap:12px;align-items:center;padding:13px 16px;border-top:1px solid var(--line);font-size:13px}.service:first-child{border-top:0}.service-name{font-weight:750}.type{font-size:11px;color:var(--muted);margin-top:3px}.badge{font-size:11px;font-weight:700;padding:4px 7px;border-radius:20px;background:rgba(53,213,139,.12);color:var(--green);display:inline-block}.badge.wait{background:rgba(255,184,74,.12);color:var(--orange)}.quick{display:grid;gap:8px}.quick a{display:flex;justify-content:space-between;background:var(--card2);border:1px solid var(--line);padding:12px;color:#dce9f4;text-decoration:none;border-radius:7px;font-size:13px}.row{display:grid;grid-template-columns:1fr auto;gap:10px;padding:12px 16px;border-top:1px solid var(--line);font-size:13px}.row:first-child{border-top:0}.empty{padding:25px 16px;color:var(--muted);font-size:13px}.mobilebar{display:none}.section-actions{display:flex;gap:7px}.money{font-weight:750}.footer{padding:20px 0;color:#526d83;font-size:11px;text-align:center}@media(max-width:950px){.app{grid-template-columns:1fr}.sidebar{display:none}.mobilebar{display:flex;position:sticky;top:0;z-index:5;background:var(--side);border-bottom:1px solid var(--line);padding:12px 16px;justify-content:space-between}.content{padding:17px}.stats{grid-template-columns:1fr 1fr}.main-grid{grid-template-columns:1fr}.service{grid-template-columns:1fr auto}.service .hide-mobile{display:none}}@media(max-width:520px){.stats{grid-template-columns:1fr 1fr}.top{align-items:flex-start;flex-direction:column;gap:12px}.profile{width:100%}}
</style></head><body><div class="mobilebar"><strong>NOD<b>EXA</b></strong><a href="/" style="color:#fff;text-decoration:none">Panel →</a></div><div class="app"><aside class="sidebar"><div class="logo">NOD<b>EXA</b></div><div class="group">KUNDEPORTAL</div><nav class="nav"><a class="active" href="/client"><i>⌂</i>Dashboard</a><a href="#services"><i>▣</i>Mine services</a><a href="#vps"><i>☁</i>Mine VPS'er</a><a href="#invoices"><i>▤</i>Fakturaer</a><a href="#tickets"><i>◉</i>Support</a></nav><div class="group">KONTO</div><nav class="nav"><a href="/store"><i>＋</i>Bestil service</a><a href="/account"><i>⚙</i>Min konto</a><a href="/"><i>↗</i>Serverpanel</a></nav></aside><main class="content"><header class="top"><div><h1>Dashboard</h1><div class="muted">Velkommen, {{ $user->username ?? $user->name ?? $user->email }}</div></div><div class="profile">{{ $user->email }}</div></header>@if(session('success'))<div style="background:rgba(53,213,139,.12);color:var(--green);border:1px solid rgba(53,213,139,.25);padding:12px;border-radius:7px;margin-bottom:16px">{{session('success')}}</div>@endif
<section class="stats"><div class="stat"><div class="label">Spilservere</div><div class="num">{{$services->count()}}</div></div><div class="stat"><div class="label">VPS'er</div><div class="num">{{$vpsServices->count()}}</div></div><div class="stat"><div class="label">Ubetalte fakturaer</div><div class="num">{{$invoices->where('status','unpaid')->count()}}</div></div><div class="stat"><div class="label">Åbne tickets</div><div class="num">{{$tickets->where('status','!=','closed')->count()}}</div></div></section>
<div class="main-grid"><div><section class="panel" id="services"><div class="head"><h2>Mine spilservere</h2><a class="btn" href="/store/games">Bestil server</a></div>@forelse($services as $s)<div class="service"><div><div class="service-name">{{$s->name??('Server #'.$s->id)}}</div><div class="type">Spilserver · #{{$s->id}}</div></div><div class="hide-mobile"><span class="badge">{{$s->status??'active'}}</span></div><div class="hide-mobile muted">Administrér i serverpanelet</div><a class="btn secondary" href="/">Åbn</a></div>@empty<div class="empty">Du har ingen spilservere endnu.</div>@endforelse</section>
<section class="panel" id="vps"><div class="head"><h2>Mine VPS'er</h2><a class="btn" href="/store/vps">Bestil VPS</a></div>@forelse($vpsServices as $v)<div class="service"><div><div class="service-name">{{$v->hostname?:('VPS #'.$v->id)}}</div><div class="type">{{$v->ip_address?:'Afventer IP'}} · OS ID {{$v->os_id?:'—'}}</div></div><div class="hide-mobile"><span class="badge {{$v->status==='awaiting_payment'?'wait':''}}">{{str_replace('_',' ',$v->status)}}</span></div><div class="hide-mobile muted">Flax #{{$v->provider_server_id?:'—'}}</div><a class="btn secondary" href="#vps">Detaljer</a></div>@empty<div class="empty">Du har ingen VPS'er endnu.</div>@endforelse</section>
<section class="panel" id="invoices"><div class="head"><h2>Fakturaer</h2></div>@forelse($invoices as $i)<div class="row"><div><strong>{{$i->number??('Faktura #'.$i->id)}}</strong><div class="type">Forfalder {{isset($i->due_at)?date('d/m/Y',strtotime($i->due_at)):'—'}}</div></div><div style="text-align:right"><div class="money">{{number_format((float)($i->total??0),2,',','.')}} {{$i->currency??'DKK'}}</div><span class="badge {{$i->status==='unpaid'?'wait':''}}">{{$i->status}}</span></div></div>@empty<div class="empty">Ingen fakturaer endnu.</div>@endforelse</section></div>
<aside><section class="panel"><div class="head"><h2>Hurtige handlinger</h2></div><div class="body quick"><a href="/store/vps"><span>Bestil VPS</span><b>→</b></a><a href="/store/games"><span>Bestil spilserver</span><b>→</b></a><a href="#new-ticket"><span>Opret support ticket</span><b>→</b></a><a href="/account"><span>Kontoindstillinger</span><b>→</b></a></div></section><section class="panel" id="tickets"><div class="head"><h2>Seneste tickets</h2></div>@forelse($tickets->take(5) as $t)<a href="/client/tickets/{{$t->id}}" style="color:inherit;text-decoration:none"><div class="row"><div><strong>{{$t->subject}}</strong><div class="type">#{{$t->id}}</div></div><span class="badge {{$t->status==='closed'?'':'wait'}}">{{$t->status}}</span></div></a>@empty<div class="empty">Ingen tickets endnu.</div>@endforelse</section><section class="panel" id="new-ticket"><div class="head"><h2>Ny support ticket</h2></div><form method="POST" action="/client/tickets" class="body">@csrf<input name="subject" required placeholder="Emne" style="width:100%;background:var(--card2);border:1px solid var(--line);color:white;padding:10px;border-radius:6px;margin-bottom:8px"><select name="department" style="width:100%;background:var(--card2);border:1px solid var(--line);color:white;padding:10px;border-radius:6px;margin-bottom:8px"><option value="support">Support</option><option value="billing">Fakturering</option><option value="sales">Salg</option></select><textarea name="message" required placeholder="Beskriv hvad vi kan hjælpe med..." rows="5" style="width:100%;resize:vertical;background:var(--card2);border:1px solid var(--line);color:white;padding:10px;border-radius:6px;margin-bottom:8px"></textarea><button class="btn" type="submit">Opret ticket</button></form></section></aside></div><div class="footer">Nodexa Kundeportal</div></main></div></body></html>